-- mvtk/core/anim_index.lua
--
-- Runtime lookup for the atlas animation manifest generated by the editor
-- bake. Defold cannot enumerate atlas animations at runtime, so callers must
-- use this data instead of treating pcall(sprite.play_flipbook, ...) as an
-- existence check (a missing animation logs an engine error but does not throw).

local Util = require "mvtk.core.util"

local M = {}

-- The generated index is a required build resource. A literal require keeps
-- it visible to Defold's dependency scanner; a dynamic require can be omitted
-- from release bundles and makes missing-animation checks permissive.
local DATA = require "developer.config.atlas_animations_generated"

local function normalize_id(value)
    local id = Util.normalize_hash_string(value, { keep_unknown = true })
    if not id then
        return nil
    end
    return tostring(id)
end

local function normalize_atlas_path(value)
    local path = normalize_id(value)
    if not path or path == "" then
        return nil
    end
    path = path:gsub("\\", "/")
    if path:sub(1, 1) ~= "/" then
        path = "/" .. path
    end
    return path
end

-- Animation playback ids are engine hashes even though atlas properties are text.
-- Index the manifest's known names directly; never reverse an opaque engine id.
local animation_hashes = {}
local function contains_animation(atlas, id)
    if type(id) ~= "userdata" then return atlas[id] == true end
    local lookup = animation_hashes[atlas]
    if not lookup then
        lookup = {}
        for name, present in pairs(atlas) do
            if present == true then lookup[hash(name)] = true end
        end
        animation_hashes[atlas] = lookup
    end
    return lookup[id] == true
end

--- Return true when an animation is listed, false when a known atlas omits it,
--- and nil when the atlas is absent from the generated manifest.
function M.has(atlas_path, anim)
    local atlas_key = normalize_atlas_path(atlas_path)
    local anim_key = type(anim) == "userdata" and anim or normalize_id(anim)
    if not atlas_key then
        return nil
    end
    if not anim_key or anim_key == "" then
        return false
    end

    local atlases = type(DATA) == "table" and DATA.atlases or nil
    local atlas = type(atlases) == "table" and atlases[atlas_key] or nil
    if type(atlas) ~= "table" then
        return nil
    end
    return contains_animation(atlas, anim_key)
end

--- Return the first candidate known to exist in an atlas. For an atlas the
--- manifest does not know yet, preserve legacy behaviour by returning the first
--- candidate so developer-provided art remains visible until the next bake.
function M.first_present(atlas_path, candidates)
    if type(candidates) ~= "table" then
        return nil
    end

    local atlas_key = normalize_atlas_path(atlas_path)
    local atlases = type(DATA) == "table" and DATA.atlases or nil
    local atlas = atlas_key and type(atlases) == "table" and atlases[atlas_key] or nil
    if type(atlas) ~= "table" then
        return candidates[1]
    end

    for _, candidate in ipairs(candidates) do
        local anim_key = type(candidate) == "userdata" and candidate or normalize_id(candidate)
        if anim_key and anim_key ~= "" and contains_animation(atlas, anim_key) then
            return candidate
        end
    end
    return nil
end

return M
